"""RobotClient：话题、服务和参数检查都对齐 C++ 版。"""

import json
import math
import re

from dobot.msg import (
    ClearErrors,
    EnableMotors,
    GamepadState,
    GoHome,
    IMUState,
    LowerCmd,
    LowerState,
    RemoteControl,
    SetCalibrationFlag,
    SetFsmId,
    StandingControl,
    UpperCmd,
    UpperState,
)
from dobot.srv import (
    CallRpc,
    ExecuteSkill,
    GetFsmId,
    GetFsmList,
    PlayPresetAction,
    SetRobotMode,
    SetVelocity,
)
from rclpy.node import Node
from rclpy.qos import DurabilityPolicy, HistoryPolicy, QoSProfile, ReliabilityPolicy


class DobotError(RuntimeError):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


class ClientConfig:
    def __init__(self):
        self.model = "SR_3588"
        self.robot_ip = ""
        self.rpc_port = 51234
        self.ros_topic_prefix = ""
        self.service_prefix = "/dobot"


# 固件里这些话题是 BEST_EFFORT。RELIABLE 的订阅端订不上 BEST_EFFORT 的写端。
# 其余话题（使能、清错、回零、标定、状态机、站立）按 RELIABLE。
_BEST_EFFORT_TOPICS = frozenset({
    "lower/state", "upper/state", "pelvis/imu/data", "torso/imu/data", "gamepad/state",
    "lower/cmd", "upper/cmd", "remote/control",
})


def _qos(suffix):
    reliability = (
        ReliabilityPolicy.BEST_EFFORT if suffix in _BEST_EFFORT_TOPICS
        else ReliabilityPolicy.RELIABLE
    )
    return QoSProfile(
        history=HistoryPolicy.KEEP_LAST,
        depth=1,
        reliability=reliability,
        durability=DurabilityPolicy.VOLATILE,
    )


# 预设动作名到状态机编号。与 C++ 的 AutoEnterBox、AutoExitBox、LieDown、GoProne、StandUpFromSupine、StandUpFromProne 一致。
PRESET_ACTIONS = {
    "auto_enter_box": 307,
    "auto_exit_box": 308,
    "lie_down": 310,
    "stand_up_supine": 311,
    "go_prone": 312,
    "stand_up_prone": 313,
}

_FSM_NAMES = {
    0: "零力矩",
    1: "阻尼",
    2: "底层调试",
    100: "预备站立",
    300: "站立",
    304: "拟人行走",
    307: "自主入箱",
    308: "自主出箱",
    310: "躺下",
    311: "仰姿起身",
    312: "趴下",
    313: "俯姿起身",
}

_METHOD_NAME = re.compile(r"^[A-Za-z_.][A-Za-z0-9_.]*\Z")


def fsm_id_to_string(fsm_id):
    """把已知状态机编号翻成短字符串；未知编号返回 unknown(<id>)。350–400 是舞蹈。"""
    if fsm_id in _FSM_NAMES:
        return _FSM_NAMES[fsm_id]
    if 350 <= fsm_id <= 400:
        return "舞蹈"
    return "unknown(%d)" % fsm_id


def _finite(value):
    return isinstance(value, (int, float)) and math.isfinite(value)


def _check_motor(motor):
    for name in ("q", "dq", "tau", "kp", "kd"):
        if not _finite(getattr(motor, name)):
            raise DobotError(2, "电机命令里有非有限浮点。")
    if motor.kp < 0 or motor.kd < 0:
        raise DobotError(2, "kp 和 kd 不能为负。")


class RobotClient:
    """一行 init 之后用 subscribe_* / publish_* / call_*。节点生命周期仍由调用方 spin。"""

    def __init__(self, node: Node):
        self._node = node
        self._config = ClientConfig()
        self._ready = False
        self._pubs = {}
        self._clients = {}

    def init(self, config=None):
        """检查型号。不连不上机器人也可以继续用话题。"""
        self._config = config or ClientConfig()
        if self._config.model not in ("SR_3588", "SR_thor"):
            raise DobotError(2, "未知型号。当前支持 SR_3588 和 SR_thor。")
        if not self._config.robot_ip:
            self._config.robot_ip = "172.16.20.2" if self._config.model == "SR_thor" else "192.168.5.2"
        self._ready = True
        return True

    def _require(self):
        if not self._ready:
            raise DobotError(1, "先调用 init。")

    def _topic(self, suffix):
        name = "/" + suffix
        prefix = self._config.ros_topic_prefix
        if not prefix:
            return name
        if not prefix.startswith("/"):
            prefix = "/" + prefix
        return prefix.rstrip("/") + name

    def _service(self, suffix):
        prefix = self._config.service_prefix or "/dobot"
        return prefix.rstrip("/") + "/" + suffix

    def _sub(self, msg_type, suffix, callback):
        self._require()
        return self._node.create_subscription(msg_type, self._topic(suffix), callback, _qos(suffix))

    def subscribe_lower_state(self, callback):
        return self._sub(LowerState, "lower/state", callback)

    def subscribe_upper_state(self, callback):
        return self._sub(UpperState, "upper/state", callback)

    def subscribe_pelvis_imu(self, callback):
        return self._sub(IMUState, "pelvis/imu/data", callback)

    def subscribe_torso_imu(self, callback):
        return self._sub(IMUState, "torso/imu/data", callback)

    def subscribe_gamepad(self, callback):
        return self._sub(GamepadState, "gamepad/state", callback)

    def subscribe_fsm(self, callback):
        return self._sub(SetFsmId, "set/fsm/id", callback)

    def _pub(self, msg_type, suffix):
        self._require()
        if suffix not in self._pubs:
            self._pubs[suffix] = self._node.create_publisher(msg_type, self._topic(suffix), _qos(suffix))
        return self._pubs[suffix]

    def publish_lower_cmd(self, cmd: LowerCmd):
        for motor in cmd.motor_cmd:
            _check_motor(motor)
        self._pub(LowerCmd, "lower/cmd").publish(cmd)

    def publish_upper_cmd(self, cmd: UpperCmd):
        for motor in cmd.motor_cmd:
            _check_motor(motor)
        self._pub(UpperCmd, "upper/cmd").publish(cmd)

    def publish_standing(self, cmd: StandingControl):
        if not all(_finite(v) for v in (cmd.head_yaw, cmd.waist_yaw, cmd.body_height)):
            raise DobotError(2, "站立命令里有非有限浮点。")
        self._pub(StandingControl, "stand/cmd").publish(cmd)

    def publish_remote(self, cmd: RemoteControl):
        for name, value in (
            ("btn_move.x", cmd.btn_move.x),
            ("btn_move.y", cmd.btn_move.y),
            ("btn_turn.x", cmd.btn_turn.x),
            ("btn_turn.y", cmd.btn_turn.y),
        ):
            if not _finite(value) or value < -1.5 or value > 1.5:
                raise DobotError(2, name + " 超出 -1.5 到 1.5。")
        self._pub(RemoteControl, "remote/control").publish(cmd)

    def publish_set_fsm_id(self, cmd: SetFsmId):
        if len(cmd.current_action) > 1024:
            raise DobotError(2, "current_action 超过 1024 字节。")
        self._pub(SetFsmId, "set/fsm/id").publish(cmd)

    def publish_enable_motors(self, cmd: EnableMotors):
        self._pub(EnableMotors, "enable/motors").publish(cmd)

    def publish_clear_errors(self, cmd: ClearErrors):
        self._pub(ClearErrors, "clear/errors").publish(cmd)

    def publish_go_home(self, cmd: GoHome):
        self._pub(GoHome, "go/home").publish(cmd)

    def publish_calibration_flag(self, cmd: SetCalibrationFlag):
        self._pub(SetCalibrationFlag, "set/calibration/flag").publish(cmd)

    def _client(self, srv_type, suffix):
        self._require()
        if suffix not in self._clients:
            self._clients[suffix] = self._node.create_client(srv_type, self._service(suffix))
        return self._clients[suffix]

    def call_get_fsm_id(self, timeout_sec=3.0):
        """同步调用。调用方需要在另一个线程 spin，或者用 rclpy 的 executor。"""
        client = self._client(GetFsmId, "get_fsm_id")
        if not client.wait_for_service(timeout_sec=timeout_sec):
            raise DobotError(8, "服务不可用。先启动 dobot_motion_service。")
        request = GetFsmId.Request()
        request.timeout_ms = int(timeout_sec * 1000)
        future = client.call_async(request)
        return future

    def call_set_robot_mode(self, mode, timeout_sec=3.0):
        allowed = ("zero_torque", "damping", "custom_debug", "ready", "standing", "walking")
        if mode not in allowed:
            raise DobotError(2, "mode 只能是 " + "、".join(allowed) + "。")
        client = self._client(SetRobotMode, "set_robot_mode")
        if not client.wait_for_service(timeout_sec=timeout_sec):
            raise DobotError(8, "服务不可用。先启动 dobot_motion_service。")
        request = SetRobotMode.Request()
        request.mode = mode
        request.timeout_ms = int(timeout_sec * 1000)
        return client.call_async(request)

    def call_set_velocity(self, vx, vy, vyaw, duration, timeout_sec=3.0):
        if not all(_finite(v) for v in (vx, vy, vyaw, duration)) or duration < 0:
            raise DobotError(2, "速度或 duration 不合法。duration 单位是秒，不能为负。")
        client = self._client(SetVelocity, "set_velocity")
        if not client.wait_for_service(timeout_sec=timeout_sec):
            raise DobotError(8, "服务不可用。先启动 dobot_motion_service。")
        request = SetVelocity.Request()
        request.vx = float(vx)
        request.vy = float(vy)
        request.vyaw = float(vyaw)
        request.duration = float(duration)
        request.timeout_ms = int(timeout_sec * 1000)
        return client.call_async(request)

    def call_get_fsm_list(self, timeout_sec=3.0):
        """查询全部状态机，包括舞蹈。返回 future，结果里的 fsm_list 是 FsmInfo 列表。"""
        client = self._client(GetFsmList, "get_fsm_list")
        if not client.wait_for_service(timeout_sec=timeout_sec):
            raise DobotError(8, "服务不可用。先启动 dobot_motion_service。")
        request = GetFsmList.Request()
        request.timeout_ms = int(timeout_sec * 1000)
        return client.call_async(request)

    def call_play_preset_action(self, action, timeout_sec=3.0):
        """播放预设动作。成功只表示切换被接受，不表示动作做完。

        auto_exit_box、stand_up_supine、stand_up_prone 返回后先进入拟人行走（304），约 2 s 后自动进入站立（300），
        不要在返回后立刻切 standing。
        """
        if action not in PRESET_ACTIONS:
            raise DobotError(2, "action 只能是 " + "、".join(PRESET_ACTIONS) + "。")
        client = self._client(PlayPresetAction, "play_preset_action")
        if not client.wait_for_service(timeout_sec=timeout_sec):
            raise DobotError(8, "服务不可用。先启动 dobot_motion_service。")
        request = PlayPresetAction.Request()
        request.action = action
        request.timeout_ms = int(timeout_sec * 1000)
        return client.call_async(request)

    def call_execute_skill(self, file_path, timeout_sec=3.0):
        """播放机器人技能目录里的动作。file_path 是机器人上的文件名。成功只表示 RPC 被接受。"""
        if not isinstance(file_path, str) or not file_path:
            raise DobotError(2, "file_path 不能为空。它是机器人上技能目录里的文件名。")
        client = self._client(ExecuteSkill, "execute_skill")
        if not client.wait_for_service(timeout_sec=timeout_sec):
            raise DobotError(8, "服务不可用。先启动 dobot_motion_service。")
        request = ExecuteSkill.Request()
        request.file_path = file_path
        request.timeout_ms = int(timeout_sec * 1000)
        return client.call_async(request)

    def call_rpc(self, method, params=None, timeout_sec=3.0):
        """直接调用一个 JSON-RPC 方法。params 是 dict，缺省为空对象。

        结果 code 为 0 只表示传输成功，result 的业务含义看 response_json。
        """
        if not isinstance(method, str) or not _METHOD_NAME.match(method):
            raise DobotError(2, "method 只能含字母、数字、下划线和点，且不以数字开头。")
        if params is None:
            params = {}
        if not isinstance(params, dict):
            raise DobotError(2, "params 必须是 dict。")
        try:
            params_json = json.dumps(params, ensure_ascii=False, allow_nan=False)
        except (TypeError, ValueError) as error:
            raise DobotError(2, "params 不能转成 JSON：%s" % error)
        client = self._client(CallRpc, "call_rpc")
        if not client.wait_for_service(timeout_sec=timeout_sec):
            raise DobotError(8, "服务不可用。先启动 dobot_motion_service。")
        request = CallRpc.Request()
        request.method = method
        request.params_json = params_json
        request.timeout_ms = int(timeout_sec * 1000)
        return client.call_async(request)
